"""Prepare only: fresh one-order cohort, preserving every old pin; never activates admission."""
import boto3,pathlib,json,subprocess,copy,uuid,datetime,concurrent.futures,os
from botocore.config import Config
p=pathlib.Path('/private/tmp/funded-delivery-178');p.mkdir(mode=0o700,exist_ok=True);cfg=Config(connect_timeout=8,read_timeout=25);s=boto3.Session(profile_name='Wizz_stg_UserApp',region_name='us-east-1');l=s.client('lambda',config=cfg);d=s.resource('dynamodb',config=cfg)
names=json.loads(subprocess.check_output(['node','-e',"console.log(JSON.stringify(require('./scripts/check-finance-rollout-deployment.cjs').FUNCTIONS))"]))
with concurrent.futures.ThreadPoolExecutor(max_workers=4)as pool:configs=list(pool.map(lambda n:l.get_function_configuration(FunctionName=n),names))
scopes=[json.loads(c['Environment']['Variables']['FINANCE_ROLLOUT_CONFIG'])for c in configs];assert all(x==scopes[0]for x in scopes),'SCOPE_DRIFT'
old=json.loads(pathlib.Path('/private/tmp/financial-device-test-163/selector.private.json').read_text());order=d.Table('WizzOrders').get_item(Key={'PK':'ORDER#'+old['orderId'],'SK':'META'},ConsistentRead=True)['Item'];assert order['status']=='delivered'
selector={**old,'requestId':str(uuid.uuid4())};selector['orderId']=json.loads(subprocess.check_output(['node','-e',"const x=JSON.parse(require('fs').readFileSync(0,'utf8'));console.log(JSON.stringify(require('./backend/wallet-service/dist/deliveryQuoteOrder').orderIdFor(x.userId,x.requestId)))"],input=json.dumps(selector).encode()))
assert not d.Table('WizzOrders').get_item(Key={'PK':'ORDER#'+selector['orderId'],'SK':'META'},ConsistentRead=True).get('Item')
current=copy.deepcopy(scopes[0]);previous=next(x for x in current['scopes']if any(o['orderId']==old['orderId']for o in x['orders']));fresh=copy.deepcopy(previous);previous['mode']='DRAIN';fresh.update(id='fattoush-funded-178',mode='SCOPED',admitUntil=(datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(hours=2)).isoformat(timespec='milliseconds').replace('+00:00','Z'),orders=[{'orderId':selector['orderId'],'branchId':selector['branchId'],'customerSubjectId':fresh['orders'][0]['customerSubjectId']}]);current['scopes'].append(fresh)
digest=json.loads(subprocess.check_output(['node','-e',"console.log(JSON.stringify(require('./backend/wallet-service/dist/deliveryQuoteRecord').quoteHash(JSON.parse(require('fs').readFileSync(0,'utf8')))))"],input=json.dumps(current).encode()));changes={'FINANCE_ROLLOUT_CONFIG':json.dumps(current,separators=(',',':')),'FINANCE_ROLLOUT_SHA256':digest}
sizes=[{'function':c['FunctionName'],'bytes':len(json.dumps({**c['Environment']['Variables'],**changes},separators=(',',':'),ensure_ascii=False).encode())}for c in configs]
validation=subprocess.run(['node','-e',"const fs=require('fs'),r=JSON.parse(fs.readFileSync(0,'utf8'));const check=require('./scripts/check-finance-rollout-deployment.cjs');for(const c of r.configs){const before={AWS_REGION:'us-east-1',...c.Environment.Variables};const after={...before,...r.changes};check.preserveDrainingScopes(before,after);}console.log('All historical scope memberships preserved');"],input=json.dumps({'configs':configs,'changes':changes}).encode(),check=True,capture_output=True);assert all(x['bytes']<4096 for x in sizes),'ENVIRONMENT_VARIABLE_LIMIT';print(validation.stdout.decode().strip())
for name,data in [('selector.private.json',selector),('scope-draft.private.json',{'scope':current,'changes':changes,'configs':configs,'refreshAdmissionTimeBeforeActivation':True})]:f=p/name;f.write_text(json.dumps(data,indent=2,default=str));os.chmod(f,0o600)
r={'preparedOnly':True,'hostsAgree':len(configs),'historicalScopesPreserved':True,'previousDeliveredScopeDraining':True,'newOrderAbsent':True,'scopeCount':len(current['scopes']),'maxEnvironmentBytes':max(x['bytes']for x in sizes),'overLimitFunctions':[x for x in sizes if x['bytes']>=4096],'activated':False};pathlib.Path('docs/funded-delivery-scope-draft-178.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))

defines=json.loads(pathlib.Path('/private/tmp/financial-device-test-163/user-dart-defines.private.json').read_text());defines['FINANCE_TEST_CHECKOUT_ATTEMPT']=json.dumps({'schemaVersion':1,'userId':selector['userId'],'branchId':selector['branchId'],'requestId':selector['requestId']},separators=(',',':'));f=p/'user-dart-defines.private.json';f.write_text(json.dumps(defines,indent=2));f.chmod(0o600)
